const { Client } = require('pg');

exports.handler = async (event) => {
  const rxId = event.pathParameters.rxId;
  const patientId = event.requestContext.authorizer.claims.sub;
  const client = new Client({ connectionString: process.env.DATABASE_URL });
  await client.connect();
  const res = await client.query(
    'UPDATE prescriptions SET refill_requested = true WHERE id = $1 AND patient_id = $2 RETURNING *',
    [rxId, patientId]
  );
  await client.end();
  if (res.rows.length === 0) return { statusCode: 403, body: JSON.stringify({ error: 'Prescription not found or unauthorized' }) };
  return { statusCode: 200, body: JSON.stringify(res.rows[0]) };
};
